import{_ as t,o,c as i,a3 as a}from"./chunks/framework.DXf0zkj5.js";const g=JSON.parse('{"title":"Known Gaps, Limitations, and Unverified Paths","description":"","frontmatter":{},"headers":[],"relativePath":"KNOWN_GAPS.md","filePath":"KNOWN_GAPS.md"}'),n={name:"KNOWN_GAPS.md"};function s(r,e,c,d,l,u){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="known-gaps-limitations-and-unverified-paths" tabindex="-1">Known Gaps, Limitations, and Unverified Paths <a class="header-anchor" href="#known-gaps-limitations-and-unverified-paths" aria-label="Permalink to &quot;Known Gaps, Limitations, and Unverified Paths&quot;">​</a></h1><p>This document tracks every <code>PARTIAL</code>, <code>UNVERIFIED</code>, and documented known limitation across all implementation batches. It is maintained and updated at the completion of each batch.</p><hr><h2 id="_1-response-trailers-forwarding" tabindex="-1">1. Response Trailers Forwarding <a class="header-anchor" href="#_1-response-trailers-forwarding" aria-label="Permalink to &quot;1. Response Trailers Forwarding&quot;">​</a></h2><ul><li><strong>Feature</strong>: Response forwarding (Feature 9)</li><li><strong>Status / Limitation</strong>: Known limitation (trailers dropped)</li><li><strong>What is missing</strong>: Forwarding of HTTP/1.1 chunked response trailers to the client.</li><li><strong>Why</strong>: RFC 9110 chunked trailer parsing and client stream framing was deferred to maintain simplicity in streaming pipelines in Batch 2.</li><li><strong>What would verify it</strong>: A real origin sending chunked transfer with trailing headers (e.g. <code>Trailer: Server-Timing</code>, followed by trailer fields after the final 0-length chunk), asserting the client receives those trailer headers.</li></ul><hr><h2 id="_2-response-header-filtering" tabindex="-1">2. Response Header Filtering <a class="header-anchor" href="#_2-response-header-filtering" aria-label="Permalink to &quot;2. Response Header Filtering&quot;">​</a></h2><ul><li><strong>Feature</strong>: Response header security filtering (Feature 91 / 150)</li><li><strong>Status / Limitation</strong>: Not yet implemented / Out of scope for Batches 1–2</li><li><strong>What is missing</strong>: Security filtering of response headers (e.g., stripping internal debug headers, enforcing CORS or CSP policies, removing sensitive server identity headers).</li><li><strong>Why</strong>: Explicitly designated as a security batch feature.</li><li><strong>What would verify it</strong>: Automated unit and integration tests asserting that configured restricted response headers from upstream are stripped prior to forwarding to downstream clients.</li></ul><hr><h2 id="_3-advanced-upstream-tls-custom-cas-mtls-resolved-in-batch-15" tabindex="-1">3. Advanced Upstream TLS (Custom CAs &amp; mTLS) (Resolved in Batch 15) <a class="header-anchor" href="#_3-advanced-upstream-tls-custom-cas-mtls-resolved-in-batch-15" aria-label="Permalink to &quot;3. Advanced Upstream TLS (Custom CAs &amp; mTLS) (Resolved in Batch 15)&quot;">​</a></h2><ul><li><strong>Feature</strong>: Upstream connections (Feature 7 / 80 / 83)</li><li><strong>Status / Limitation</strong>: Fully resolved in Batch 15</li><li><strong>Resolution</strong>: <ul><li>Implemented upstream HTTPS with custom CA bundles, SNI hostname propagation, connection pooling/reuse, and health breaker integration.</li><li>Implemented client certificate authentication (mTLS) with required, optional, and off modes, exposing verified client identities (subject, SAN, fingerprint) on request context for downstream auth batches.</li><li>Implemented upstream mTLS client certificate presentation and zero-downtime rotation.</li><li>Verified via <code>tests/tls-upstream.test.ts</code> and <code>tests/mtls.test.ts</code>.</li></ul></li></ul><hr><h2 id="_4-upstream-connect-timeout-on-non-routable-ip-rfc-5737" tabindex="-1">4. Upstream Connect Timeout on Non-Routable IP (RFC 5737) <a class="header-anchor" href="#_4-upstream-connect-timeout-on-non-routable-ip-rfc-5737" aria-label="Permalink to &quot;4. Upstream Connect Timeout on Non-Routable IP (RFC 5737)&quot;">​</a></h2><ul><li><strong>Feature</strong>: Timeouts (Feature 12)</li><li><strong>Status / Limitation</strong>: Partially environment-dependent</li><li><strong>What is missing</strong>: Complete isolation of the connect timeout on environments where the kernel immediately rejects 192.0.2.1 with &quot;network unreachable&quot; (EHOSTUNREACH / ENETUNREACH) returning 502 instead of hanging until timeout (504).</li><li><strong>Why</strong>: Operating system networking stacks vary: some drop SYN packets and wait for TCP timeout, while others immediately return ICMP Destination Unreachable. Both paths are handled safely (504 on timeout, 502 on unreachable).</li><li><strong>What would verify it</strong>: Running behind a packet filtering firewall (<code>pf</code> on macOS or <code>iptables -j DROP</code> on Linux) that silently drops SYN packets destined for the test IP, guaranteeing a TCP connection hang.</li></ul><hr><h2 id="_5-http-2-and-http-3-support" tabindex="-1">5. HTTP/2 and HTTP/3 Support <a class="header-anchor" href="#_5-http-2-and-http-3-support" aria-label="Permalink to &quot;5. HTTP/2 and HTTP/3 Support&quot;">​</a></h2><ul><li><strong>Feature</strong>: Protocol support</li><li><strong>Status / Limitation</strong>: Known architectural limitation (Out of scope)</li><li><strong>What is missing</strong>: HTTP/2 (RFC 9113) and HTTP/3 (RFC 9114 / QUIC) transport protocols on both client listener and upstream connections.</li><li><strong>Why</strong>: The proxy core is intentionally implemented for HTTP/1.1 and HTTP/1.0. The specification states: &quot;Do NOT implement HTTP/2 or HTTP/3. Say so in KNOWN_GAPS.md.&quot;</li><li><strong>What would verify it</strong>: TLS ALPN negotiation with <code>h2</code> or <code>h3</code>, binary framing parsers, multiplexed stream listeners, and end-to-end multi-stream test suites.</li></ul><hr><h2 id="_6-multiple-origins-routing-resolved-in-batch-11" tabindex="-1">6. Multiple Origins Routing (Resolved in Batch 11) <a class="header-anchor" href="#_6-multiple-origins-routing-resolved-in-batch-11" aria-label="Permalink to &quot;6. Multiple Origins Routing (Resolved in Batch 11)&quot;">​</a></h2><ul><li><strong>Feature</strong>: Multiple origins (Feature 54)</li><li><strong>Status / Limitation</strong>: Fully resolved in Batch 11</li><li><strong>Resolution</strong>: <ul><li>Implemented declarative request routing across multiple origins via <code>originRoutes</code> (<code>pathPrefix</code>, <code>pathPattern</code>, <code>host</code>, <code>header</code>).</li><li>Implemented origin pools (<code>originPools</code>), member weighting (<code>weight</code>), and load balancing policies (<code>round-robin</code>, <code>least-connections</code>, <code>weighted</code>).</li><li>Verified via <code>tests/multiple-origins.test.ts</code>, <code>tests/origin-pools.test.ts</code>, <code>tests/weighted-routing.test.ts</code>, and <code>tests/load-balancing.test.ts</code>.</li></ul></li></ul><hr><h2 id="_7-content-length-body-validation" tabindex="-1">7. Content-Length Body Validation <a class="header-anchor" href="#_7-content-length-body-validation" aria-label="Permalink to &quot;7. Content-Length Body Validation&quot;">​</a></h2><ul><li><strong>Feature</strong>: Content-length validation (Feature 89)</li><li><strong>Status / Limitation</strong>: Not implemented / Out of scope for Batch 3</li><li><strong>What is missing</strong>: Verifying that the actual body byte count transferred over the wire strictly matches the numeric value in the <code>Content-Length</code> header, and treating discrepancies (premature close or overflow) as invalid responses.</li><li><strong>Why</strong>: Batch 3 Feature 2 (&quot;Response parsing&quot;) was explicitly scoped to structural header and status parsing: &quot;Parse ONLY structure here... and do NOT validate that bytes actually delivered match Content-Length (that is the separate &#39;Content-length validation&#39; feature; do not mark it done).&quot;</li><li><strong>What would verify it</strong>: End-to-end tests where an upstream origin sends <code>Content-Length: 100</code> but sends only 40 bytes or 150 bytes, asserting that the proxy detects the mismatch and terminates the transfer.</li></ul><hr><h2 id="_8-rfc-9111-freshness-calculation-scope-known-limitations-batches-5-6" tabindex="-1">8. RFC 9111 Freshness Calculation Scope &amp; Known Limitations (Batches 5 &amp; 6) <a class="header-anchor" href="#_8-rfc-9111-freshness-calculation-scope-known-limitations-batches-5-6" aria-label="Permalink to &quot;8. RFC 9111 Freshness Calculation Scope &amp; Known Limitations (Batches 5 &amp; 6)&quot;">​</a></h2><ul><li><strong>Feature</strong>: RFC 9111 Freshness &amp; Cache-Control (Features 19, 21, 24, 25, 45, 46, 47)</li><li><strong>Status / Limitation</strong>: Fully compliant with RFC 9111 §4.2.3 freshness lifetimes, Age calculation, and Date header handling: <ol><li><strong>Conservative Qualified Directive Handling</strong>: Directives with field lists such as <code>no-cache=&quot;Set-Cookie&quot;</code> or <code>private=&quot;X-Custom&quot;</code> are parsed into <code>noCacheFields</code> and <code>privateFields</code>, but acted upon conservatively: qualified <code>no-cache</code> is treated as unqualified <code>no-cache</code>, and qualified <code>private</code> is treated as unqualified <code>private</code> (neither is stored).</li><li><strong>Ignored Request Cache-Control Directives</strong>: Request Cache-Control directives <code>min-fresh</code>, <code>max-stale</code>, <code>only-if-cached</code>, and non-zero <code>max-age</code> are fully parsed by the scanner but ignored during lookup. Only request <code>no-cache</code>, <code>no-store</code>, and <code>max-age=0</code> act as cache bypass triggers.</li><li><strong>Heuristic Freshness (Implemented in Batch 6)</strong>: RFC 9111 §4.2.2 heuristic freshness support piece is implemented based on <code>Last-Modified</code>. Configured via <code>cache.heuristic.{enabled, ratio, maxMs}</code>. It applies ONLY when no <code>s-maxage</code>, <code>max-age</code>, or <code>Expires</code> is present, response is cacheable (not <code>no-store</code>/<code>private</code>/<code>no-cache</code>), and <code>lastModifiedMs &lt;= dateValueMs</code>.</li><li><strong>Date Header Implementation (Fully Verified in Batch 6)</strong>: Verified behavior: when the origin sends no Date header, or an invalid Date header, or multiple Date headers, the proxy synthesizes a valid IMF-fixdate <code>Date</code> header at <code>responseTime</code> from the Clock, sets <code>entry.dateSource = &#39;proxy_added&#39;</code>, sets <code>dateValueMs = responseTimeMs</code>, and logs <code>date_missing</code> or <code>date_invalid</code>. On HIT, the stored Date is replayed unchanged (and does not drift as time advances). Proxy-generated responses (error, OPTIONS *, 304, etc.) set Date = now from Clock, with Node automatic Date suppressed (<code>res.sendDate = false</code>). All Batch 5 UNVERIFIED labels are resolved and removed.</li><li><strong>Age Header Pass-through on MISS</strong>: On cache MISS responses being forwarded to the client, any origin <code>Age</code> header is passed through unchanged (accurately describing upstream caches). The proxy does not add or alter the <code>Age</code> header on MISS responses.</li><li><strong>Stale Serving &amp; Revalidation</strong>: Stale entries are NEVER served under any condition. Stale entries are lazily deleted at lookup and reported as miss reason <code>&quot;expired&quot;</code>. Therefore, <code>must-revalidate</code>, <code>proxy-revalidate</code>, <code>stale-while-revalidate</code>, and <code>stale-if-error</code> are trivially satisfied because stale entries are never served.</li><li><strong>S-maxage Precedence</strong>: Freshness lifetime calculation implements <code>s-maxage</code> &gt; <code>max-age</code> &gt; <code>Expires</code> &gt; <code>heuristic</code> &gt; <code>none</code> precedence as required for RFC 9111 shared caches; however, the separate &quot;S-maxage&quot; feature remains PARTIAL pending revalidation and surrogate control integration.</li></ol></li><li><strong>What would verify it</strong>: Future batch tests for revalidation (304), heuristic freshness (Batch 6 Last-Modified), and request freshness controls (<code>min-fresh</code>/<code>max-stale</code>).</li></ul><hr><h2 id="_9-cache-eviction-storage-subsystem-resolved-in-batch-9" tabindex="-1">9. Cache Eviction &amp; Storage Subsystem (Resolved in Batch 9) <a class="header-anchor" href="#_9-cache-eviction-storage-subsystem-resolved-in-batch-9" aria-label="Permalink to &quot;9. Cache Eviction &amp; Storage Subsystem (Resolved in Batch 9)&quot;">​</a></h2><ul><li><strong>Feature</strong>: Memory cache eviction &amp; storage (Features 27, 30, 31, 32, 33, 34, 35)</li><li><strong>Status / Limitation</strong>: Fully resolved in Batch 9</li><li><strong>Resolution</strong>: <ol><li><strong>Memory Cache (Feature 27)</strong>: Decoupled in-memory storage behind <code>ICacheStore</code> interface wired directly into proxy lookup, hit, miss, fill, and eviction paths.</li><li><strong>Metadata Index (Feature 30)</strong>: $O(1)$ key-to-metadata index storing size, status, headers, storedAt, lastAccessedAt, hitCount, and namespace; updates on hit; deletes cleanly without orphans.</li><li><strong>Object Storage (Feature 31)</strong>: Byte-accurate body storage decoupled from metadata. Streaming reads are thread-safe and immune to concurrent eviction/replacement.</li><li><strong>LRU Eviction (Feature 32)</strong>: Pluggable eviction policy evicting least recently accessed entries first, updating access order on hit and lookup.</li><li><strong>LFU Eviction (Feature 33)</strong>: Pluggable eviction policy evicting lowest frequency entries first, with deterministic tie-breaking (oldest last-access, then keyHash).</li><li><strong>TTL Eviction (Feature 34)</strong>: Identifies and evicts expired entries past all stale windows. Entries inside <code>stale-while-revalidate</code> or <code>stale-if-error</code> windows are protected from TTL eviction.</li><li><strong>Size Eviction (Feature 35)</strong>: Strictly enforces <code>maxTotalBytes</code> and <code>maxEntries</code> budgets via active eviction policy. Rejects oversized objects without partial state. Protects entries under active revalidation locks and in-flight coalescing.</li></ol></li><li><strong>Verification</strong>: Verified via <code>tests/memory-cache.test.ts</code>, <code>tests/metadata-index.test.ts</code>, <code>tests/object-storage.test.ts</code>, <code>tests/eviction-lru.test.ts</code>, <code>tests/eviction-lfu.test.ts</code>, <code>tests/eviction-ttl.test.ts</code>, and <code>tests/eviction-size.test.ts</code>.</li></ul><hr><h2 id="_9b-disk-cache-and-persistence-not-implemented-batch-9-out-of-scope" tabindex="-1">9b. Disk Cache and Persistence Not Implemented (Batch 9 Out-of-Scope) <a class="header-anchor" href="#_9b-disk-cache-and-persistence-not-implemented-batch-9-out-of-scope" aria-label="Permalink to &quot;9b. Disk Cache and Persistence Not Implemented (Batch 9 Out-of-Scope)&quot;">​</a></h2><ul><li><strong>Feature</strong>: Disk cache (Feature 28) and Persistent cache (Feature 29)</li><li><strong>Status / Limitation</strong>: Explicitly not implemented / Out of scope for Batch 9</li><li><strong>What is missing</strong>: Filesystem/block-backed disk caching, memory-to-disk tiering, and persistent cache survival across proxy process restarts. Also out of scope: segmented cache (Feature 36), namespace management (Feature 37), tenant quotas (Feature 38), and per-tenant object limits (Feature 39).</li><li><strong>Why</strong>: Batch 9 explicitly confines storage and eviction to the in-memory store architecture. The storage interface (<code>ICacheStore</code>, <code>MetadataIndex</code>, <code>ObjectStore</code>) is intentionally decoupled to allow pluggable disk and persistent backends in future batches.</li><li><strong>What would verify it</strong>: Future batch test suites using persistent disk-backed stores, crash-recovery tests, and cross-restart cache hit verification.</li></ul><hr><h2 id="_10-vary-header-handling" tabindex="-1">10. Vary Header Handling <a class="header-anchor" href="#_10-vary-header-handling" aria-label="Permalink to &quot;10. Vary Header Handling&quot;">​</a></h2><ul><li><strong>Feature</strong>: Vary header support (Feature 94)</li><li><strong>Status / Limitation</strong>: Responses with <code>Vary</code> are bypassed and not stored</li><li><strong>What is missing</strong>: Storing and selecting secondary cache variants based on request headers specified in the origin&#39;s <code>Vary</code> response header (e.g., <code>Vary: Accept-Encoding, Accept-Language</code>).</li><li><strong>Why</strong>: Storing responses that carry <code>Vary</code> headers without full secondary variant indexing risks serving the wrong variant to subsequent clients with different capabilities.</li><li><strong>What would verify it</strong>: Multi-variant integration tests verifying that distinct <code>Accept-Encoding</code> variants (e.g. gzip vs br vs identity) are stored and matched independently.</li></ul><hr><h2 id="_11-request-coalescing-stampede-prevention-resolved-in-batch-8" tabindex="-1">11. Request Coalescing / Stampede Prevention (Resolved in Batch 8) <a class="header-anchor" href="#_11-request-coalescing-stampede-prevention-resolved-in-batch-8" aria-label="Permalink to &quot;11. Request Coalescing / Stampede Prevention (Resolved in Batch 8)&quot;">​</a></h2><ul><li><strong>Feature</strong>: Request coalescing / Stampede prevention (Features 50 &amp; 51)</li><li><strong>Status / Limitation</strong>: Fully resolved in Batch 8</li><li><strong>Resolution</strong>: <ol><li><strong>Cold-Miss Request Coalescing (Feature 50)</strong>: Multiple concurrent misses for the identical cache key collapse into exactly 1 in-flight upstream request. Followers await leader completion and are served directly from cache store upon leader fill.</li><li><strong>Stampede Prevention on Expiry (Feature 51)</strong>: 50 concurrent requests on an expired entry collapse into exactly 1 upstream conditional revalidation request (reducing upstream requests from 50 down to 1).</li><li><strong>Replacement Delivery</strong>: On 200 replacement during revalidation, the leader streams and writes the new body into cache store before resolving followers, ensuring all waiting clients receive the updated body.</li><li><strong>Collapsed Forwarding Note (Feature 52)</strong>: Collapsed forwarding of concurrent misses is structurally covered by Request Coalescing (Feature 50). Feature 52 is not marked DONE pending explicit routing and backend scope definitions.</li></ol></li><li><strong>Verification</strong>: Verified via <code>tests/coalescing.test.ts</code> (5 concurrency tests) and <code>tests/stampede.test.ts</code> (6 concurrency tests, tested up to 100 parallel requests).</li></ul><hr><h2 id="_12-age-and-date-headers-on-cache-hit" tabindex="-1">12. Age and Date Headers on Cache Hit <a class="header-anchor" href="#_12-age-and-date-headers-on-cache-hit" aria-label="Permalink to &quot;12. Age and Date Headers on Cache Hit&quot;">​</a></h2><ul><li><strong>Feature</strong>: Age header / Date header generation (Features 46 &amp; 47, RFC 9111 §5.1 &amp; §5.6.1)</li><li><strong>Status / Limitation</strong>: Fully implemented and verified in Batches 5 &amp; 6</li><li><strong>Implementation</strong>: <code>Age</code> header calculation and injection implemented in Batch 5; <code>Date</code> header policy, IMF-fixdate formatting, origin Date validation, proxy-generated Date headers, and HIT replay implemented in Batch 6.</li><li><strong>Verification</strong>: Verified via <code>tests/age-header.test.ts</code> and <code>tests/date-header.test.ts</code>.</li></ul><hr><h2 id="_13-head-method-bypass" tabindex="-1">13. HEAD Method Bypass <a class="header-anchor" href="#_13-head-method-bypass" aria-label="Permalink to &quot;13. HEAD Method Bypass&quot;">​</a></h2><ul><li><strong>Feature</strong>: HTTP method caching (Feature 47)</li><li><strong>Status / Limitation</strong>: Temporary bypass for HEAD requests</li><li><strong>What is missing</strong>: Serving HEAD requests directly from existing cached GET responses without contacting origin, or caching HEAD responses.</li><li><strong>Why</strong>: Batch 4 scope fence specifies a conservative policy where only GET is cached, and HEAD bypasses cache lookup (<code>reason: method_not_cacheable</code>).</li><li><strong>What would verify it</strong>: A test verifying that a HEAD request for an entry primed via GET is served as a cache HIT with stored headers and an empty body.</li></ul><hr><h2 id="_14-client-conditionals-upstream-miss-limitation-resolved-in-batch-7" tabindex="-1">14. Client Conditionals &amp; Upstream Miss Limitation (Resolved in Batch 7) <a class="header-anchor" href="#_14-client-conditionals-upstream-miss-limitation-resolved-in-batch-7" aria-label="Permalink to &quot;14. Client Conditionals &amp; Upstream Miss Limitation (Resolved in Batch 7)&quot;">​</a></h2><ul><li><strong>Feature</strong>: Client Conditional Requests (Features 20, 21, 22, 23, 40, 42, 43)</li><li><strong>Status / Limitation</strong>: Fully resolved in Batch 7</li><li><strong>Resolution</strong>: <ol><li><strong>200-to-Conditional Filling</strong>: When a client conditional request (<code>If-None-Match</code> or <code>If-Modified-Since</code>) misses in cache and reaches the origin, an origin 200 response is now fully storable under normal rules (removing the Batch 6 <code>conditional_request_miss</code> skip reason). If origin answers 304 on a true miss, it passes through unstored with <code>origin_304_no_entry</code>.</li><li><strong>Upstream 304 Processing &amp; Freshness Recompute</strong>: Origin 304 responses refresh stored headers and recompute freshness lifetimes per RFC 9111 §3.2.</li><li><strong>Proactive Upstream Revalidation</strong>: Stale entries with validators trigger synchronous conditional revalidation.</li><li><strong>Bypass for Other Conditionals</strong>: <code>If-Match</code>, <code>If-Unmodified-Since</code>, <code>If-Range</code>, and <code>Range</code> continue to bypass cache lookup (<code>reason: method_not_cacheable</code> or <code>conditional_request</code>). 412 Precondition Failed and 206 Partial Content are not generated.</li></ol></li></ul><hr><h2 id="_15-validator-processing-constraints-edge-cases-batch-6" tabindex="-1">15. Validator Processing Constraints &amp; Edge Cases (Batch 6) <a class="header-anchor" href="#_15-validator-processing-constraints-edge-cases-batch-6" aria-label="Permalink to &quot;15. Validator Processing Constraints &amp; Edge Cases (Batch 6)&quot;">​</a></h2><ul><li><strong>Feature</strong>: Validators and Heuristic Freshness (Features 20, 21)</li><li><strong>Status / Limitation</strong>: Documented validator edge cases</li><li><strong>Details</strong>: <ol><li><strong>Multiple or Invalid Validators</strong>: An origin response with multiple <code>ETag</code> or multiple <code>Last-Modified</code> headers, or an unparseable validator, is treated as having no usable validator (<code>entry.etag = undefined</code>, <code>entry.lastModifiedMs = undefined</code>), and logs <code>etag_multiple</code>, <code>etag_invalid</code>, or <code>last_modified_multiple</code>. The response is still storable if explicit freshness directives exist, and raw headers are replayed on HIT, but it cannot answer client conditional requests with 304 (always serves 200).</li><li><strong>Last-Modified Later Than Date</strong>: An origin response whose <code>Last-Modified</code> header is strictly after its <code>Date</code> header does not receive heuristic freshness (<code>lifetime = 0</code>, skipped with <code>reason: no_freshness_info</code>).</li><li><strong>Unused <code>strongMatch</code></strong>: <code>strongMatch</code> is fully implemented and tested in <code>src/cache/etag.ts</code>, but unused in Batch 6 because RFC 9110 §13.1.2 mandates weak comparison for <code>If-None-Match</code>. Reserved for future range or <code>If-Match</code> features.</li><li><strong>Obsolete Warning Header Not Implemented</strong>: RFC 9111 §5.5 obsoleted the <code>Warning</code> header (e.g., <code>Warning: 113 - &quot;Heuristic Expiration&quot;</code>). The proxy does not generate or attach <code>Warning</code> headers to responses using heuristic freshness.</li></ol></li></ul><hr><h2 id="_16-batch-7-8-revalidation-scope-fence-gaps-and-baselines" tabindex="-1">16. Batch 7 &amp; 8 Revalidation Scope Fence, Gaps, and Baselines <a class="header-anchor" href="#_16-batch-7-8-revalidation-scope-fence-gaps-and-baselines" aria-label="Permalink to &quot;16. Batch 7 &amp; 8 Revalidation Scope Fence, Gaps, and Baselines&quot;">​</a></h2><ul><li><strong>Feature</strong>: Revalidation &amp; RFC 9111 Shared Cache Control (Features 40, 42, 43, 151, 152) and Stale Serving / SWR / SIE (Features 26, 41, 44, 49, 145)</li><li><strong>Status / Limitation</strong>: Documented constraints and resolutions: <ol><li><strong>Stampede Baseline on Stale Entries (Resolved in Batch 8)</strong>: The Batch 7 baseline (50 concurrent requests on a single stale entry produce 50 origin requests) is fully resolved. Under Feature 51 (Stampede prevention), 50 concurrent stale requests collapse to exactly 1 upstream conditional revalidation.</li><li><strong>Stale Serving Scope Fence (Resolved in Batch 8)</strong>: Features 26 (<code>stale-while-revalidate</code>), 41 (<code>Background revalidation</code>), 44 (<code>Stale serving</code>), 49 (<code>Revalidation locks</code>), and 145 (<code>stale-if-error</code>) are implemented and verified. Stale serving is safely permitted within RFC 5861 windows, while <code>must-revalidate</code>, <code>proxy-revalidate</code>, and <code>s-maxage</code> strictly override and forbid stale delivery.</li><li><strong>Validator Mismatch Response</strong>: When an origin 304 returns an ETag that does not weak-match the stored entry, the proxy logs <code>validator_mismatch</code>, deletes the stale entry, and responds with <code>502 Bad Gateway</code> (<code>UPSTREAM_INVALID_RESPONSE</code>) without transparent retry. A future retry / unconditional revalidation feature may upgrade this path.</li><li><strong>Always-Revalidate Entries Not Stored</strong>: Responses with <code>no-cache</code>, <code>private</code>, <code>no-store</code>, <code>max-age=0</code>, or zero lifetime are not stored, even when they carry validators. Supporting always-revalidate entries (storing <code>no-cache</code> or <code>max-age=0</code> responses alongside an ETag to serve only via 304) is tracked as a future optimization.</li><li><strong>Last-Modified Not Compared on 304 Refresh</strong>: In <code>applyNotModified</code>, when an origin responds with 304, only <code>ETag</code> is checked for validator mismatch (using RFC 9111 weak comparison). <code>Last-Modified</code> is not compared for mismatch because HTTP date formatting variants, intermediary timestamp roundtrips, and 1-second resolution differences make date inequality unreliable as an indicator of representation corruption.</li><li><strong>Cancelled Revalidations</strong>: If a client aborts/disconnects during synchronous revalidation, the proxy aborts the in-flight upstream request, changes nothing in the cache store, and does not refresh the entry. Under request coalescing, a follower aborting does not cancel the leader request.</li><li><strong>Request <code>Cache-Control: no-cache</code></strong>: An incoming client request with <code>Cache-Control: no-cache</code> (or <code>Pragma: no-cache</code>) bypasses the cache entirely and fetches fresh content from origin, rather than triggering a conditional revalidation against cached content.</li></ol></li></ul><hr><h2 id="_17-batch-10-scope-fence-out-of-scope-items-and-architectural-boundaries" tabindex="-1">17. Batch 10 Scope Fence, Out-of-Scope Items, and Architectural Boundaries <a class="header-anchor" href="#_17-batch-10-scope-fence-out-of-scope-items-and-architectural-boundaries" aria-label="Permalink to &quot;17. Batch 10 Scope Fence, Out-of-Scope Items, and Architectural Boundaries&quot;">​</a></h2><ul><li><strong>Feature</strong>: Disk Cache, Persistence, Segmentation, Namespaces, Quotas &amp; Limits (Features 28, 29, 36, 37, 38, 39)</li><li><strong>Status / Limitation</strong>: Documented constraints and explicit scope boundaries: <ol><li><strong>Purge APIs (Features 118–128) NOT Implemented</strong>: <ul><li>Explicit programmatic cache invalidation endpoints (URL purge, surrogate-key purge, tag purge, wildcard purge) are NOT implemented in Batch 10 and remain strictly out of scope. Deletion occurs solely through internal eviction (TTL, capacity, LRU/LFU/SLRU, and tenant quotas).</li></ul></li><li><strong>Compaction (Feature 146) NOT Implemented</strong>: <ul><li>Background storage compaction, defragmentation, and disk hole-punching are NOT implemented. Disk files are deleted via atomic <code>fs.unlinkSync()</code>.</li></ul></li><li><strong>Origin Validation (Feature 48) &amp; Consistent Hashing (Feature 148) NOT Implemented</strong>: <ul><li>Upstream origin certificate validation and consistent hashing topologies remain out of scope for Batch 10.</li></ul></li><li><strong>Relationship between Request Coalescing (Feature 50) and Collapsed Forwarding (Feature 52)</strong>: <ul><li>Feature 50 (Request Coalescing, implemented in Batch 8) structurally accomplishes collapsed forwarding: concurrent requests for the same cold cache key coalesce into a single upstream request, and all followers are satisfied from the resulting cached representation.</li><li>However, per Batch 10 requirements, Feature 52 is NOT marked DONE in Batch 10 and remains reserved for its designated milestone.</li></ul></li><li><strong>Directory Scaling &amp; Sharding</strong>: <ul><li><code>DiskStore</code> stores objects in a flat directory (<code>&lt;dirPath&gt;/&lt;hexKeyHash&gt;.cache</code>). For deployments with tens of millions of entries, two-level directory sharding (e.g., <code>ab/cd/&lt;hash&gt;.cache</code>) to avoid filesystem directory entry bottlenecks is deferred to a future performance milestone.</li></ul></li><li><strong>Checksum Algorithm</strong>: <ul><li>File integrity uses SHA-256 (32 bytes in a 48-byte header). Hardware-accelerated CRC32c or xxHash is reserved for future high-throughput optimization.</li></ul></li></ol></li></ul><hr><h2 id="_18-health-checks-failover-circuit-breaker-dns-refresh-resolved-in-batch-12" tabindex="-1">18. Health Checks, Failover, Circuit Breaker &amp; DNS Refresh (Resolved in Batch 12) <a class="header-anchor" href="#_18-health-checks-failover-circuit-breaker-dns-refresh-resolved-in-batch-12" aria-label="Permalink to &quot;18. Health Checks, Failover, Circuit Breaker &amp; DNS Refresh (Resolved in Batch 12)&quot;">​</a></h2><ul><li><strong>Feature</strong>: Health Checks, Failover, Circuit Breaker, DNS Refresh (Features 57, 58, 59, 60, 61, 64)</li><li><strong>Status / Limitation</strong>: Fully resolved in Batch 12</li><li><strong>Resolution</strong>: <ol><li><strong>Passive Health Checks (Feature 60)</strong>: Live request outcome tracking with sliding-window consecutive failure counting, 4xx/client abort exclusion, and automatic cooldown recovery.</li><li><strong>Active Health Checks (Feature 59)</strong>: Background periodic HTTP/HTTPS health probes with dual-threshold hysteresis (<code>healthyThreshold</code> / <code>unhealthyThreshold</code>), non-overlapping probe locks, and clean timer teardown.</li><li><strong>Health Routing (Feature 57)</strong>: Integrated compound availability predicate <code>isAvailable(originId)</code> into <code>PoolSelector</code> across round-robin, least-connections, and weighted load balancing policies, with graceful 502 fallback when all origins are unhealthy.</li><li><strong>Failover Origins (Feature 58)</strong>: Primary member prioritization with ordered backup failover, immediate recovery return, and invariant cache keys across failover.</li><li><strong>Circuit Breaker (Feature 61)</strong>: Per-origin tri-state circuit breaker (<code>CLOSED</code>, <code>OPEN</code>, <code>HALF_OPEN</code>) with zero-upstream-attempt rejection in <code>OPEN</code> and trial request concurrency limiting in <code>HALF_OPEN</code>.</li><li><strong>DNS Refresh (Feature 64)</strong>: Proactive background DNS cache refreshment ahead of expiry without blocking requests, with bounded stale fallback on resolution failure and request coalescing.</li></ol></li><li><strong>Verification</strong>: Verified via <code>tests/passive-health-checks.test.ts</code>, <code>tests/active-health-checks.test.ts</code>, <code>tests/health-routing.test.ts</code>, <code>tests/failover-origins.test.ts</code>, <code>tests/circuit-breaker.test.ts</code>, <code>tests/dns-refresh.test.ts</code>, and <code>tests/batch-12-cross-cutting.test.ts</code>.</li></ul><hr><h2 id="_20-compression-content-negotiation-resolved-in-batch-13" tabindex="-1">20. Compression &amp; Content Negotiation (Resolved in Batch 13) <a class="header-anchor" href="#_20-compression-content-negotiation-resolved-in-batch-13" aria-label="Permalink to &quot;20. Compression &amp; Content Negotiation (Resolved in Batch 13)&quot;">​</a></h2><ul><li><strong>Feature</strong>: Compression and Content Negotiation (Features 66, 67, 68, 69, 70, 71, 72, 73)</li><li><strong>Status / Limitation</strong>: Fully resolved in Batch 13</li><li><strong>Resolution</strong>: <ol><li><strong>Accept-Encoding Parsing (Feature 70)</strong>: Parses complex Accept-Encoding headers with quality values (q-values), tokens, <code>q=0</code> explicit refusal, wildcard <code>*</code>, <code>identity</code>, case-insensitivity, and bound on malformed input without crash.</li><li><strong>Content Negotiation (Feature 69)</strong>: Negotiates optimal encoding based on client q-values and deterministic proxy codec preference order (<code>zstd</code> &gt; <code>br</code> &gt; <code>gzip</code>). Emits <code>Vary: Accept-Encoding</code> on all negotiated and cacheable responses.</li><li><strong>Gzip Streaming (Feature 66)</strong>: Streaming compression and decompression using native <code>node:zlib</code> with backpressure and bounded memory on 10MB+ streams. ETag weakened (<code>W/</code>) per RFC 9110. Decompression bomb protection with configurable <code>maxDecompressedBytes</code>.</li><li><strong>Brotli Streaming (Feature 67)</strong>: Streaming Brotli compression and decompression using native <code>node:zlib.createBrotliCompress</code> / <code>createBrotliDecompress</code>.</li><li><strong>Zstandard Streaming (Feature 68)</strong>: Streaming Zstandard compression and decompression using native Node 22 <code>node:zlib.createZstdCompress</code> / <code>createZstdDecompress</code> with no third-party dependencies.</li><li><strong>Compression Levels (Feature 72)</strong>: Configurable per-codec levels (<code>gzip: 1-9</code>, <code>br: 0-11</code>, <code>zstd: 1-22</code>) with startup range validation and safe defaults (<code>gzip: 6</code>, <code>br: 4</code>, <code>zstd: 3</code>).</li><li><strong>Content-Type Rules (Feature 73)</strong>: Built-in compressible patterns (<code>text/*</code>, <code>application/json</code>, <code>*+json</code>, <code>*+xml</code>, <code>image/svg+xml</code>, <code>application/javascript</code>, <code>application/wasm</code>) and incompressible patterns (<code>image/*</code>, <code>video/*</code>, <code>audio/*</code>, <code>application/zip</code>, <code>font/woff2</code>). Configurable allow and deny list overrides with parameter stripping and case insensitivity.</li><li><strong>Compression Bypass (Feature 71)</strong>: Authoritative bypass checks for body size below threshold (<code>&lt; minBytes</code>), <code>Cache-Control: no-transform</code>, origin already-encoded response, non-compressible content types, <code>Range</code> or <code>206 Partial Content</code>, HTTP 204/304, <code>HEAD</code> requests, and configured bypass headers/routes. Bypass reasons exposed via <code>X-Compression-Bypass</code> debug header.</li></ol></li><li><strong>Verification</strong>: Verified via <code>tests/accept-encoding.test.ts</code>, <code>tests/content-negotiation.test.ts</code>, <code>tests/gzip.test.ts</code>, <code>tests/brotli.test.ts</code>, <code>tests/zstandard.test.ts</code>, <code>tests/compression-levels.test.ts</code>, <code>tests/content-type-rules.test.ts</code>, <code>tests/compression-bypass.test.ts</code>, and <code>tests/batch-13-cross-cutting.test.ts</code>.</li></ul><hr><h2 id="_22-range-requests-partial-caching-payload-framing-resolved-in-batch-14" tabindex="-1">22. Range Requests, Partial Caching &amp; Payload Framing (Resolved in Batch 14) <a class="header-anchor" href="#_22-range-requests-partial-caching-payload-framing-resolved-in-batch-14" aria-label="Permalink to &quot;22. Range Requests, Partial Caching &amp; Payload Framing (Resolved in Batch 14)&quot;">​</a></h2><ul><li><strong>Feature</strong>: Range Requests, Partial Caching, Chunked Transfer, Content-Length Validation, Binary Content (Features 74, 75, 76, 77, 78)</li><li><strong>Status / Limitation</strong>: Fully resolved in Batch 14</li><li><strong>Resolution</strong>: <ol><li><strong>Range Requests (Feature 74)</strong>: <ul><li>RFC 9110 Section 14.1.2 single byte-range parser (<code>bytes=start-end</code>, <code>bytes=start-</code>, <code>bytes=-suffix</code>) handling whitespace, multiple ranges (first range selection), and invalid/unsatisfiable syntax returning 416 Range Not Satisfiable with <code>Content-Range: bytes */total</code>.</li><li>RFC 9110 Section 13.1.2 <code>If-Range</code> conditional evaluation against ETag (strong match per RFC) and Last-Modified date (exact HTTP date match). On match, serves 206 Partial Content; on mismatch, serves 200 OK complete body.</li></ul></li><li><strong>Partial Caching (Feature 75)</strong>: <ul><li>Directly synthesizes and serves HTTP 206 Partial Content slices directly out of complete cached 200 OK objects in MemoryStore/DiskStore without contacting origin.</li><li>Sets exact <code>Content-Range: bytes start-end/total</code>, exact <code>Content-Length: slice.length</code>, and <code>Accept-Ranges: bytes</code>.</li></ul></li><li><strong>Chunked Transfer (Feature 76)</strong>: <ul><li>Clean streaming of origin chunked transfer-encoding responses (<code>Transfer-Encoding: chunked</code>) to downstream clients.</li><li>Strips hop-by-hop <code>Content-Length</code> header on chunked proxy responses per RFC 9112 Section 6.3.</li><li>Assembles and stores cacheable chunked origin responses into coherent cache entries served with exact <code>Content-Length</code> on subsequent cache hits.</li></ul></li><li><strong>Content-Length Validation (Feature 77)</strong>: <ul><li>Enforces exact byte counting on response bodies with <code>Content-Length</code>.</li><li>Premature EOF / Underrun drop: Discards partial responses on premature upstream connection close, does not store corrupted partial objects in cache, and aborts downstream socket.</li><li>Overrun smuggling guard: Detects excess bytes beyond declared <code>Content-Length</code>, immediately aborts stream and closes sockets to prevent HTTP request/response smuggling.</li></ul></li><li><strong>Binary Content (Feature 78)</strong>: <ul><li>Transparent, bit-identical preservation for arbitrary octet streams (<code>application/octet-stream</code>), binary media (<code>image/png</code>, <code>video/mp4</code>, <code>audio/mpeg</code>), embedded null bytes (<code>0x00</code>), and non-UTF-8 byte sequences (<code>0x80</code>–<code>0xFF</code>).</li><li>Preserves SHA-256 byte identity across origin, proxy streaming, cache storage, and cache hits.</li></ul></li></ol></li><li><strong>Verification</strong>: Verified via <code>tests/range-requests.test.ts</code>, <code>tests/partial-caching.test.ts</code>, <code>tests/chunked-transfer.test.ts</code>, <code>tests/content-length-validation.test.ts</code>, and <code>tests/binary-content.test.ts</code>.</li></ul><hr><h2 id="_23-batch-14-scope-fence-out-of-scope-items-and-architectural-boundaries" tabindex="-1">23. Batch 14 Scope Fence, Out-of-Scope Items, and Architectural Boundaries <a class="header-anchor" href="#_23-batch-14-scope-fence-out-of-scope-items-and-architectural-boundaries" aria-label="Permalink to &quot;23. Batch 14 Scope Fence, Out-of-Scope Items, and Architectural Boundaries&quot;">​</a></h2><ul><li><strong>Feature</strong>: Range Requests, Partial Caching &amp; Payload Framing (Features 74, 75, 76, 77, 78)</li><li><strong>Status / Limitation</strong>: Documented constraints and explicit scope boundaries: <ol><li><strong>TLS Termination and Upstream TLS (Features 79–83) NOT Implemented</strong>: <ul><li>TLS termination, certificate configuration, certificate rotation, upstream TLS, and mTLS are strictly out of scope for Batch 14 and reserved for Batch 15.</li></ul></li><li><strong>Security, Auth &amp; Filtering (Features 84–91, 150) NOT Implemented</strong>: <ul><li>API-key authentication, JWT/OIDC, origin access control, IP allow/denylists, and header filtering are reserved for Batch 16.</li></ul></li><li><strong>Metrics &amp; Logging (Features 92–104) NOT Implemented</strong>: <ul><li>Prometheus exposition, OpenTelemetry traces, structured/request logging, and latency metrics are reserved for Batches 17 and 18.</li></ul></li><li><strong>Cache Purge APIs (Features 118–128) NOT Implemented</strong>: <ul><li>Programmatic cache invalidation (URL, tag, surrogate-key) is reserved for Batch 19.</li></ul></li></ol></li></ul><hr><h2 id="_24-opentelemetry-otlp-exporter-limits-batch-17-scope-boundaries" tabindex="-1">24. OpenTelemetry OTLP Exporter Limits &amp; Batch 17 Scope Boundaries <a class="header-anchor" href="#_24-opentelemetry-otlp-exporter-limits-batch-17-scope-boundaries" aria-label="Permalink to &quot;24. OpenTelemetry OTLP Exporter Limits &amp; Batch 17 Scope Boundaries&quot;">​</a></h2><ul><li><strong>Feature</strong>: OpenTelemetry (Feature 93) &amp; Batch 17 Observability</li><li><strong>Status / Limitation</strong>: Documented architectural limits for native OTLP export: <ol><li><strong>Zero External SDKs Constraint</strong>: <ul><li>The proxy intentionally avoids heavy external dependencies (<code>@opentelemetry/sdk-trace-base</code>, <code>@opentelemetry/exporter-trace-otlp-http</code>).</li><li>Tracing uses native W3C Trace Context formatting and an in-memory <code>SpanExporter</code>.</li></ul></li><li><strong>OTLP/HTTP JSON Limits</strong>: <ul><li>OTLP export is implemented via lightweight HTTP POST carrying OTLP JSON (<code>v1/traces</code>).</li><li>Protobuf encoding (gRPC / <code>application/x-protobuf</code>) is <strong>not supported</strong>; only JSON encoding is emitted.</li><li>Transport compression (e.g. gzip-compressed OTLP batches) is not enabled by default for export payloads.</li><li>Retries on network failure follow a simple single retry policy without persistent disk-spooled queues.</li></ul></li><li><strong>Batch 17 Out-of-Scope Items</strong>: <ul><li>Latency histograms (origin latency, proxy latency), revalidation counters, eviction counters, and upstream error classification are deferred to Batch 18.</li><li>Web UI Dashboard and cache overview visualization (Features 105, 106) are deferred to subsequent UI batches.</li></ul></li></ol></li></ul><hr><h2 id="_25-advanced-metrics-resolution-batch-18-scope-boundaries" tabindex="-1">25. Advanced Metrics Resolution &amp; Batch 18 Scope Boundaries <a class="header-anchor" href="#_25-advanced-metrics-resolution-batch-18-scope-boundaries" aria-label="Permalink to &quot;25. Advanced Metrics Resolution &amp; Batch 18 Scope Boundaries&quot;">​</a></h2><ul><li><strong>Feature</strong>: Features 100–104 (Origin Latency, Proxy Latency, Eviction Metrics, Revalidation Metrics, Upstream Errors)</li><li><strong>Status / Limitation</strong>: Fully resolved in Batch 18 with native Prometheus histogram generation and multi-dimensional counters: <ol><li><strong>Histogram Bounds</strong>: <ul><li>Prometheus histograms use native fixed cumulative buckets. Exponential histograms or dynamic bucket allocation are not used to guarantee bounded memory.</li></ul></li><li><strong>Batch 18 Out-of-Scope Items</strong>: <ul><li>Web UI Dashboard and cache overview visualization (Features 105–117) are deferred to Batch 19 (Frontend / Operations).</li><li>Cache Purge APIs (Features 118–128) are deferred to Batch 20 (Purge &amp; Control APIs).</li></ul></li></ol></li></ul>',74)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
